import { audioKey } from "./piperCore";

/**
 * Pre-recorded audio shipped with the app (public/audio/<lang>/, generated by scripts/generate-audio.mjs).
 * The manifest lists available keys so we never request a file that doesn't exist.
 */
const manifests = new Map<string, Promise<Set<string>>>();

function audioBase(): string {
  return `${import.meta.env.BASE_URL}audio/`;
}

function loadManifest(base: string): Promise<Set<string>> {
  let m = manifests.get(base);
  if (!m) {
    m = fetch(`${audioBase()}${base}/index.json`)
      .then((r) => (r.ok ? r.json() : { keys: [] }))
      .then((j: { keys?: string[] }) => new Set(j.keys ?? []))
      .catch(() => new Set<string>());
    manifests.set(base, m);
  }
  return m;
}

/** URL of the recording for this text, or null when there is none. */
export async function recordedUrl(text: string, base: string): Promise<string | null> {
  const keys = await loadManifest(base);
  const key = audioKey(text);
  return keys.has(key) ? `${audioBase()}${base}/${key}.mp3` : null;
}

/** For tests. */
export function resetRecordedAudio(): void {
  manifests.clear();
}
